import React from "react";
import {
  DataTable,
  TableContainer,
  Table,
  TableHead,
  TableHeaderCell,
  TableBody,
  TableRow,
  TableCell,
  ActionButtons,
  TableButton,
} from "./StyledComponents";

const AllUsers = ({ users = [], handleDeleteUser }) => {
  // console.log("spots received in component:", spots);

  return (
    <DataTable>
      <TableContainer>
        <Table>
          <TableHead>
            <tr>
              <TableHeaderCell>Name</TableHeaderCell>
              <TableHeaderCell>Email</TableHeaderCell>
              <TableHeaderCell>Aktion</TableHeaderCell>
            </tr>
          </TableHead>

          <TableBody>
            {Array.isArray(users) && users.length > 0 ? (
              users.map((user) => (
                <TableRow key={user.id}>
                  <TableCell>{user.name || "-"}</TableCell>
                  <TableCell>{user.email || "-"}</TableCell>
                  <TableCell>
                    <ActionButtons>
                      {/* <TableButton className="edit" onClick={() => handleEditSpot(spot)}>
                        ✏️
                      </TableButton> */}
                      <TableButton
                        className="delete"
                        onClick={() => handleDeleteUser(user.id)}
                      >
                        🗑️
                      </TableButton>
                    </ActionButtons>
                  </TableCell>
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan="4" style={{ textAlign: "center", padding: "1rem" }}>
                  Keine Pflegeplätze gefunden.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>
    </DataTable>
  );
};


export default AllUsers;
