import React from "react";
import {
  DataTable,
  TableHeader,
  TableTitle,
  AddButton,
  TableContainer,
  Table,
  TableHead,
  TableHeaderCell,
  TableBody,
  TableRow,
  TableCell,
  ActionButtons,
  TableButton,
} from "./StyledComponents";

const SpotsSection = ({ spots = [], setShowAddPage, handleDeleteSpot, handleEditSpot }) => {
  // console.log("spots received in component:", spots);

  return (
    <DataTable>
      <TableHeader>
        <TableTitle>Meine Pflegeplätze</TableTitle>
        <AddButton onClick={() => setShowAddPage(true)}>+ Neu hinzufügen</AddButton>
      </TableHeader>

      <TableContainer>
        <Table>
          <TableHead>
            <tr>
              <TableHeaderCell>Name</TableHeaderCell>
              <TableHeaderCell>Zimmer</TableHeaderCell>
              <TableHeaderCell>Preis</TableHeaderCell>
              <TableHeaderCell>Verfügbarkeit</TableHeaderCell>
              <TableHeaderCell>Pflegestufe</TableHeaderCell>
              <TableHeaderCell>Aktion</TableHeaderCell>
            </tr>
          </TableHead>

          <TableBody>
            {Array.isArray(spots) && spots.length > 0 ? (
              spots.map((spot) => (
                <TableRow key={spot.id}>
                  <TableCell>{spot.name_of_the_place || "-"}</TableCell>
                 <TableCell>
                  {spot.room_type === "1"
                    ? "Einzelzimmer"
                    : spot.room_type === "2"
                    ? "Doppelzimmer"
                    : "-"
                  }
                </TableCell>

                  <TableCell>{spot.price_per_month ? `€${spot.price_per_month}` : "-"}</TableCell>
                  <TableCell>
                  {spot.availability === "1"
                    ? "Sofort"
                    : spot.availability === "2"
                    ? "Kurzfristig"
                    : spot.availability === "3"
                    ? "1–3 Monate"
                    : "-"
                  }
                </TableCell>
                <TableCell>
                  {spot.care_level === "1"
                    ? "Stufe 1"
                    : spot.care_level === "2"
                    ? "Stufe 2"
                    : spot.care_level === "3"
                    ? "Stufe 3"
                    : "-"
                  }
                </TableCell>
                  <TableCell>
                    <ActionButtons>
                      <TableButton className="edit" onClick={() => handleEditSpot(spot)}>
                        ✏️
                      </TableButton>
                      <TableButton
                        className="delete"
                        onClick={() => handleDeleteSpot(spot.id)}
                      >
                        🗑️
                      </TableButton>
                    </ActionButtons>
                  </TableCell>
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan="4" style={{ textAlign: "center", padding: "1rem" }}>
                  Keine Pflegeplätze gefunden.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>
    </DataTable>
  );
};


export default SpotsSection;
