import React, { useState, useEffect } from 'react';
// import styled from 'styled-components';
import axios from "axios";
import { BaseUrl } from "../BaseUrl";
import { Container, Title, Form, SearchHeader, Subtitle, Row, Label, Input, Select, SearchBtn, ResultsGrid, Card, Name, Address, Detail, Details, ButtonContainer, DetailsBtn, BackButton, HeaderCard, HeaderTitle, HeaderSub, HeaderActions, PrimaryBtn, GhostBtn, DetailGrid, InfoCard, SectionTitle, KV, Key, Value, ContactBox, ContactRow, AboutCard, Bullet, FormField, TextArea, SubmitBtn, SuccessAlert } from "./Styles";
import Pagination from "./Pagination";



// ================================================

export default function SearchPage() {
  const [view, setView] = useState('search');
  const [selectedFacility, setSelectedFacility] = useState(null);
  const [results, setResults] = useState([]);
  const [cityList, setCityList] = useState([]);
  const [pagination, setPagination] = useState({
    current_page: 1,
    last_page: 1,
    per_page: 10,
  });
  const [filters, setFilters] = useState({
    postal_code: '',
    city: '',
    distance: '',
    care_level: '',
    room_type: '',
    availability: '',
     lat: null,
    lng: null
  });

  const [showContact, setShowContact] = useState(false);
  const [contact, setContact] = useState({ name: '', phone: '', msg: '' });

  // ⭐ SUCCESS MESSAGE STATE (Added)
  const [successMsg, setSuccessMsg] = useState("");
  const token = localStorage.getItem("pflegeUserToken");
  useEffect(() => {
  navigator.geolocation.getCurrentPosition((position) => {
    setFilters((prev) => ({
      ...prev,
      lat: position.coords.latitude,
      lng: position.coords.longitude
    }));
  });
}, []);


  useEffect(() => {
    fetchSpots();
    fetchCities();
  }, []);

  const fetchCities = async () => {
    try {
      const res = await axios.get(`${BaseUrl}cities`);
      setCityList(res.data.data);
    } catch (error) {
      console.log("City fetch error:", error);
    }
  };

  const fetchSpots = async (page = 1) => {
    try {
      const res = await axios.get(`${BaseUrl}allspots?page=${page}`);

      const api = res.data?.data;

      setResults(api.data); // main data array
      setPagination({
        current_page: api.current_page,
        last_page: api.last_page,
        per_page: api.per_page,
      });

    } catch (error) {
      console.error("Error fetching spots:", error);
    }
  };

  const handleSearch = async (e, page = 1) => {
    e.preventDefault();
    try {
      if (!filters.lat || !filters.lng) {
        alert("Location is not available yet. Please allow location access.");
        return;
      }
      const query = new URLSearchParams({ ...filters, page }).toString();
      const response = await axios.get(`${BaseUrl}search?${query}`);

      const api = response.data.data;

      setResults(api.data);
      setPagination({
        current_page: api.current_page,
        last_page: api.last_page,
        per_page: api.per_page,
      });

    } catch (error) {
      console.log(error);
    }
  };




  const openDetail = (fac) => {
    setSelectedFacility(fac);
    setView('detail');
    window.scrollTo(0, 0);
  };

  // // ⭐ Updated sendContact (logic same)
  // const sendContact = (e) => {
  //   e.preventDefault();

  //   if (!contact.name.trim() || !contact.phone.trim()) {
  //     return;
  //   }

  //   setSuccessMsg("Ihre Anfrage wurde erfolgreich übermittelt!");
  //   setContact({ name: '', phone: '', msg: '' });

  //   setTimeout(() => {
  //     setSuccessMsg("");
  //     setShowContact(false);
  //   }, 2500);
  // };
 const handleSubmit = async (e) => {
  e.preventDefault();

  try {
    await axios.post(`${BaseUrl}send-inquiry`, {
      facility_id: selectedFacility.id,    // ⭐ Correct
      name: contact.name,
      phone: contact.phone,
      message: contact.msg
    });

    setSuccessMsg("Ihre Anfrage wurde erfolgreich übermittelt!");
    setContact({ name: "", phone: "", msg: "" });

    setTimeout(() => {
      setShowContact(false);
      setSuccessMsg("");
    }, 2500);

  } catch (err) {
    console.error(err);
    alert("Error sending message!");
  }
};


  return (
    <Container>
      {view === 'search' && (
        <>
          <SearchHeader>
            <Title>Pflegeheim finden</Title>
            <Subtitle>Das passende Heim für Ihre Liebsten – schnell und einfach</Subtitle>
          </SearchHeader>

          <Form onSubmit={handleSearch}>
            <Row>
              <div><Label>PLZ</Label><Input placeholder="z.B. 53111" onChange={e => setFilters({ ...filters, postal_code: e.target.value })} /></div>
              <div><Label>Stadt</Label>
                <Select onChange={e => setFilters({ ...filters, city: e.target.value })}>
                  <option value="">Alle</option>
                  {cityList.map((item, index) => (
                    <option key={index} value={item.city}>
                      {item.city}
                    </option>
                  ))}
                </Select>

              </div>
              <div><Label>Entfernung (km)</Label><Input type="number" placeholder="30" onChange={e => setFilters({ ...filters, distance: e.target.value })} /></div>
            </Row>
            <Row>
              <div><Label>Pflegestufe</Label><Select onChange={e => setFilters({ ...filters, care_level: e.target.value })}>
                <option value="">Alle</option><option value="1">Stufe1</option><option value="2">Stufe2</option><option value="3">Stufe3</option>
              </Select></div>
              <div><Label>Zimmerart</Label><Select onChange={e => setFilters({ ...filters, room_type: e.target.value })}>
                <option value="">Alle</option><option value="1">Einzel Zimmer</option><option value="2">Doppel Zimmer</option>
              </Select></div>
              <div><Label>Verfügbarkeit</Label><Select onChange={e => setFilters({ ...filters, availability: e.target.value })}>
                <option value="">Alle</option><option value="1">Sofort</option><option value="2">Kurzfristig</option><option value="3">1–3 Monate</option>
              </Select></div>
            </Row>
            <SearchBtn type="submit">Suchen</SearchBtn>
          </Form>

          {/* <h2 style={{color: '#2c3e50', margin: '1.5rem 0 1rem'}}>{results.length} Einrichtungen gefunden</h2> */}
          <h2 style={{ color: '#2c3e50', margin: '1.5rem 0 1rem' }}>
            {results.length} Einrichtungen gefunden
          </h2>

          <ResultsGrid>
            {results.map(f => (
              <Card key={f.id}>
                <Name>{f.name_of_the_place}</Name>
                <Address>{f.address}</Address>
                <Details>
                  <Detail>
                    <span>Pflege</span>
                    <strong>
                      {f.care_level === "1"
                        ? "Stufe 1"
                        : f.care_level === "2"
                          ? "Stufe 2"
                          : f.care_level === "3"
                            ? "Stufe 3"
                            : "-"}
                    </strong>
                  </Detail>

                  <Detail><span>Zimmer</span><strong>
                    {f.room_type === "1"
                      ? "SEinzelzimmertufe"
                      : f.room_type === "2"
                        ? "Doppelzimmer"
                        : "-"}
                  </strong></Detail>
                  <Detail><span>Verfügbarkeit</span>
                    {f.availability === "1"
                      ? "Sofort"
                      : f.availability === "2"
                        ? "Kurzfristig"
                        : f.availability === "3"
                          ? "1–3 Monate"
                          : "-"
                    }
                  </Detail>
                  <Detail><span>Preis</span><strong>{f.price_per_month}</strong></Detail>
                </Details>
                <ButtonContainer>
                  <DetailsBtn onClick={() => openDetail(f)}>Details anzeigen</DetailsBtn>
                </ButtonContainer>
              </Card>
            ))}
          </ResultsGrid>
          <Pagination
            currentPage={pagination.current_page}
            lastPage={pagination.last_page}
            onPageChange={(page) => fetchSpots(page)}
          />
        </>
      )}

      {view === 'detail' && selectedFacility && (
        <>
          <BackButton onClick={() => setView('search')}>← Zurück zur Suche</BackButton>

          {/* Header card like screenshot */}
          <HeaderCard>
            <div>
              <HeaderTitle>{selectedFacility.name_of_the_place}</HeaderTitle>
              <HeaderSub>{selectedFacility.address}</HeaderSub>
            </div>
            <HeaderActions>
              <PrimaryBtn onClick={() => setShowContact(true)}>Jetzt kontaktieren</PrimaryBtn>
              <GhostBtn onClick={() => setView('search')}>Zurück zur Suche</GhostBtn>
            </HeaderActions>
          </HeaderCard>

          <DetailGrid>
            {/* Left: Available places */}
            <InfoCard>
              <SectionTitle>Verfügbare Plätze</SectionTitle>
              <KV><Key>Pflegestufe</Key><Value>
                {selectedFacility.care_level === "1"
                  ? "Stufe 1"
                  : selectedFacility.care_level === "2"
                    ? "Stufe 2"
                    : selectedFacility.care_level === "3"
                      ? "Stufe 3"
                      : "-"}
              </Value></KV>
              <KV><Key>Zimmerart</Key><Value>
                {selectedFacility.room_type === "1"
                  ? "SEinzelzimmertufe"
                  : selectedFacility.room_type === "2"
                    ? "Doppelzimmer"
                    : "-"}
              </Value></KV>
              <KV><Key>Verfügbarkeit</Key><Value>
                {selectedFacility.availability === "1"
                  ? "Sofort"
                  : selectedFacility.availability === "2"
                    ? "Kurzfristig"
                    : selectedFacility.availability === "3"
                      ? "1–3 Monate"
                      : "-"
                }
              </Value></KV>
              <KV><Key>Preis pro Monat</Key><Value>{selectedFacility.price_per_month}</Value></KV>
            </InfoCard>

            {/* Right: Contact information + (toggle) contact form */}
            <InfoCard>
              <SectionTitle>Kontaktinformationen</SectionTitle>
              <ContactBox>
                <ContactRow>📞 <span>0251 654321</span></ContactRow>
                <ContactRow>✉️ <span>info@st-josef.de</span></ContactRow>
              </ContactBox>

              {showContact && (
                <div style={{ marginTop: '1rem' }}>
                  <SectionTitle style={{ marginBottom: '0.4rem' }}>Nachricht senden</SectionTitle>

                  {successMsg && <SuccessAlert>{successMsg}</SuccessAlert>}

                  <form onSubmit={handleSubmit}>
                    <FormField
                      placeholder="Name"
                      value={contact.name}
                      onChange={e => setContact({ ...contact, name: e.target.value })}
                      required
                    />
                    <FormField
                      placeholder="Telefon"
                      value={contact.phone}
                      onChange={e => setContact({ ...contact, phone: e.target.value })}
                      required
                    />
                    <TextArea
                      placeholder="Nachricht (optional)"
                      value={contact.msg}
                      onChange={e => setContact({ ...contact, msg: e.target.value })}
                    />
                    <SubmitBtn type="submit">Absenden</SubmitBtn>
                    {' '}
                    <GhostBtn type="button" onClick={() => setShowContact(false)}>Schließen</GhostBtn>
                  </form>
                </div>
              )}
            </InfoCard>

            {/* Bottom: About section (static text placeholder like screenshot) */}
            <AboutCard>
              <SectionTitle>Über die Einrichtung</SectionTitle>
              <p style={{ color: '#6b7b86', marginTop: 0 }}>
                Traditionelle Pflegeeinrichtung mit familiärer Atmosphäre.
              </p>
              <div>
                <p style={{ color: '#23384a', fontWeight: 600, marginBottom: '0.4rem' }}>Services:</p>
                <ul style={{ paddingLeft: '1.2rem', margin: 0 }}>
                  <Bullet>Vollstationäre Pflege</Bullet>
                  <Bullet>Demenzbetreuung</Bullet>
                  <Bullet>Kurzzeitpflege</Bullet>
                  <Bullet>Tagespflege</Bullet>
                </ul>
              </div>
            </AboutCard>
          </DetailGrid>
        </>
      )}
    </Container>
  );
}
