import React, { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import styled from "styled-components";
import axios from "axios";
import { BaseUrl } from "../BaseUrl"; // 👈 BaseUrl सही path पर होना चाहिए

// ====================== STYLES ======================
const Container = styled.div`
  max-width: 460px;
  margin: 2rem auto;
  padding: 2rem;
`;

const FormCard = styled.div`
  background-color: white;
  padding: 2rem;
  border-radius: 15px;
  width: 25.5rem;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
`;

const Title = styled.h1`
  color: #2c3e50;
  margin-bottom: 1.5rem;
  text-align: center;
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 1rem;
`;

const FormGroup = styled.div`
  display: flex;
  flex-direction: column;
`;

const Label = styled.label`
  margin-bottom: 0.5rem;
  color: #2c3e50;
  font-weight: 500;
`;

const Input = styled.input`
  padding: 0.75rem;
  border: 2px solid gray;
  border-radius: 8px;
  font-size: 1rem;
  transition: border-color 0.3s;
  &:focus {
    outline: none;
    border-color: #3498db;
  }
`;

const Button = styled.button`
  background-color: #3498db;
  color: white;
  padding: 1rem;
  border: none;
  border-radius: 8px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.3s;
  &:hover {
    background-color: #2980b9;
  }
`;

const ToggleSection = styled.div`
  text-align: center;
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid #e9ecef;
`;

const ToggleText = styled.span`
  color: #7f8c8d;
  margin-right: 0.5rem;
`;

const ToggleButton = styled.button`
  background-color: transparent;
  color: #3498db;
  border: none;
  cursor: pointer;
  font-weight: 600;
  text-decoration: underline;
  &:hover {
    color: #2980b9;
  }
`;

const ErrorMessage = styled.div`
  background-color: #f8d7da;
  color: #721c24;
  padding: 0.75rem;
  border-radius: 8px;
  margin-bottom: 1rem;
  text-align: center;
`;

const SuccessMessage = styled.div`
  background-color: #d4edda;
  color: #155724;
  padding: 0.75rem;
  border-radius: 8px;
  margin-bottom: 1rem;
  text-align: center;
`;

// ====================== MAIN COMPONENT ======================
function LoginRegister() {
  const navigate = useNavigate();
  const location = useLocation();
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    password: "",
  });
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  // ✅ Redirect if already logged in
  useEffect(() => {
    const isLoggedIn = localStorage.getItem("pflegeLoggedIn");
    if (isLoggedIn) navigate("/dashboard");
  }, [navigate]);

  // ✅ Handle input change
  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
    setError("");
    setSuccess("");
  };

  // ✅ API Logic
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");

    try {
      if (isLogin) {
        // ---------- LOGIN ----------
        const response = await axios.post(`${BaseUrl}login`, {
          email: formData.email.trim().toLowerCase(),
          password: formData.password,
        });

        if (response.data.success || response.data.status === true) {
          const user = response.data.user || response.data.data || {};
          const token = response.data.token || response.data.access_token || null; // ✅ Token capture

          // ✅ Save user details
          localStorage.setItem("pflegeLoggedIn", "true");
          localStorage.setItem("pflegeUserEmail", user.email);
          localStorage.setItem("pflegeUserName", user.name);
          localStorage.setItem("pflegeUserId", user.id);
          localStorage.setItem("pflegeUsertype", user.user_type);

          // ✅ Save token if present
          if (token) {
            localStorage.setItem("pflegeUserToken", token);
          }

          navigate("/dashboard");
        } else {
          setError(response.data.message || "Ungültige Anmeldedaten!");
        }
      } else {
        // ---------- REGISTER ----------
        const response = await axios.post(`${BaseUrl}register`, {
          name: formData.name.trim(),
          email: formData.email.trim().toLowerCase(),
          password: formData.password,
        });

        if (response.data.success || response.data.status === true) {
          const user = response.data.user || response.data.data || {};
          const token = response.data.token || response.data.access_token || null; // ✅ Token capture

          // ✅ Save user details
          localStorage.setItem("pflegeLoggedIn", "true");
          localStorage.setItem("pflegeUserEmail", user.email);
          localStorage.setItem("pflegeUserName", user.name);
          localStorage.setItem("pflegeUserId", user.id);
          localStorage.setItem("pflegeUsertype", user.user_type);
         

          // ✅ Save token if present
          if (token) {
            localStorage.setItem("pflegeUserToken", token);
          }

          setSuccess("Registrierung erfolgreich! Weiterleitung...");
          setTimeout(() => navigate("/dashboard"), 1500);
        } else {
          setError(response.data.message || "Registrierung fehlgeschlagen!");
        }
      }
    } catch (err) {
      console.error("API ERROR:", err);

      if (err.response) {
        // Server gave error response
        setError(err.response.data.message || JSON.stringify(err.response.data));
      } else if (err.request) {
        // Request sent but no response
        setError("Server did not respond. Check BaseUrl or API.");
      } else {
        // Other error
        setError(err.message);
      }
    }

  };

  const toggleMode = () => {
    setIsLogin(!isLogin);
    setError("");
    setSuccess("");
    setFormData({ name: "", email: "", password: "" });
  };

  return (
    <Container>
      <FormCard>
        <Title>{isLogin ? "Willkommen zurück" : "Neues Konto erstellen"}</Title>

        {error && <ErrorMessage>{error}</ErrorMessage>}
        {success && <SuccessMessage>{success}</SuccessMessage>}

        <Form onSubmit={handleSubmit}>
          {!isLogin && (
            <FormGroup>
              <Label>
                Name <span style={{ color: "red" }}>*</span>
              </Label>
              <Input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleInputChange}
                required
              />
            </FormGroup>
          )}

          <FormGroup>
            <Label>
              E-Mail-Adresse <span style={{ color: "red" }}>*</span>
            </Label>
            <Input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleInputChange}
              required
            />
          </FormGroup>

          <FormGroup>
            <Label>
              Passwort <span style={{ color: "red" }}>*</span>
            </Label>
            <Input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleInputChange}
              required
            />
          </FormGroup>

          <Button type="submit">{isLogin ? "Einloggen" : "Registrieren"}</Button>
        </Form>

        <ToggleSection>
          <ToggleText>{isLogin ? "Noch kein Konto?" : "Bereits registriert?"}</ToggleText>
          <ToggleButton type="button" onClick={toggleMode}>
            {isLogin ? "Jetzt registrieren" : "Zum Login"}
          </ToggleButton>
        </ToggleSection>

        {!isLogin && (
          <div
            style={{
              marginTop: "1rem",
              textAlign: "center",
              fontSize: "0.9rem",
              color: "#7f8c8d",
            }}
          >
            <p>* Pflichtfelder</p>
          </div>
        )}
      </FormCard>
    </Container>
  );
}

export default LoginRegister;
