import React from "react";
import {
  Sidebar,
  SidebarHeader,
  SidebarTitle,
  SidebarSubtitle,
  SidebarMenu as SidebarMenuWrapper, // ✅ renamed styled component
  MenuItem,
  MenuIcon,
} from "./StyledComponents"; // make sure this file exists in same folder
const user_type = localStorage.getItem("pflegeUsertype");

const SidebarMenu = ({ userName, activeSection, setActiveSection, handleLogout }) => {
  return (
    <Sidebar>
      <SidebarHeader>
        <SidebarTitle>Armaturenbrett</SidebarTitle>
        <SidebarSubtitle>{userName}</SidebarSubtitle>
      </SidebarHeader>

      <SidebarMenuWrapper>
        <MenuItem
          active={activeSection === "profile"}
          onClick={() => setActiveSection("profile")}
        >
          <MenuIcon /> Profil
        </MenuItem>

        <MenuItem
          active={activeSection === "spots"}
          onClick={() => setActiveSection("spots")}
        >
          <MenuIcon /> Meine Plätze
        </MenuItem>
        {user_type === 2 && (
        <MenuItem
          active={activeSection === "users"}
          onClick={() => setActiveSection("users")}
        >
          <MenuIcon /> Nutzer
        </MenuItem>
       )}

        <MenuItem onClick={handleLogout}>
          <MenuIcon /> Abmelden
        </MenuItem>
      </SidebarMenuWrapper>
    </Sidebar>
  );
};

export default SidebarMenu;
