import styled from "styled-components";

// ====================== STYLES ======================
export const Container = styled.div`
  max-width: 1300px;
  margin: 2rem auto;
  padding: 0 1rem;
`;

export const SearchHeader = styled.div`
  text-align: center;
  margin-bottom: 2rem;
`;

export const Title = styled.h1`
  color: #2c3e50;
  font-size: 2.2rem;
  margin-bottom: 0.5rem;
`;

export const Subtitle = styled.p`
  color: #7f8c8d;
  font-size: 1.1rem;
`;

export const Form = styled.form`
  background: white;
  padding: 1.5rem;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  margin-bottom: 2rem;
`;

export const Row = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.9rem;
  margin-bottom: 1rem;
`;

export const Label = styled.label`
  display: block;
  margin-bottom: 0.4rem;
  color: #34495e;
  font-size: 0.92rem;
  font-weight: 500;
`;

export const Input = styled.input`
  width: 100%;
  padding: 0.7rem;
  border: 2px solid gray;
  border-radius: 7px;
  font-size: 0.95rem;
  &:focus { outline: none; border-color: gray; }
`;

export const Select = styled.select`
  width: 100%;
  padding: 0.7rem;
  border: 2px solid gray;
  border-radius: 7px;
  font-size: 0.95rem;
  &:focus { outline: none; border-color: gray; }
`;

export const SearchBtn = styled.button`
  background: #3498db;
  color: white;
  padding: 0.75rem 2rem;
  border: none;
  border-radius: 7px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  margin: 0.8rem auto 0;
  display: block;
  &:hover { background: #2980b9; }
`;

// ====================== RESULTS PAGE ======================
export const ResultsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 1.8rem;
  margin-top: 2rem;

  @media (min-width: 1024px) {
    grid-template-columns: repeat(3, 1fr);
  }
`;

export const Card = styled.div`
  background: white;
  padding: 1.6rem;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  transition: all 0.3s;
  display: flex;
  flex-direction: column;
  height: 100%;
  &:hover { transform: translateY(-6px); box-shadow: 0 12px 25px rgba(0,0,0,0.12); }
`;

export const Name = styled.h3`
  font-size: 1.22rem;
  color: #2c3e50;
  margin: 0 0 0.5rem 0;
  flex-grow: 1;
`;

export const Address = styled.p`
  font-size: 0.88rem;
  color: #7f8c8d;
  margin: 0.5rem 0 1rem;
  line-height: 1.4;
`;

export const Details = styled.div`
  font-size: 0.88rem;
  margin-bottom: 1.2rem;
  flex-grow: 1;
`;

export const Detail = styled.div`
  display: flex;
  justify-content: space-between;
  margin: 0.45rem 0;
`;

export const ButtonContainer = styled.div`
  margin-top: auto;
  padding-top: 0.8rem;
`;

export const DetailsBtn = styled.button`
  background: #27ae60;
  color: white;
  border: none;
  padding: 0.75rem;
  border-radius: 7px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  width: 100%;
  &:hover { background: #219653; }
`;

// ====================== DETAIL PAGE ======================
export const BackButton = styled.button`
  background: none;
  border: none;
  color: #2c3e50;
  font-size: 1rem;
  cursor: pointer;
  margin-bottom: 1rem;
  opacity: 0.8;
  &:hover { text-decoration: underline; opacity: 1; }
`;

export const HeaderCard = styled.div`
  background: #ffffff;
  padding: 1.8rem;
  border-radius: 14px;
  box-shadow: 0 6px 22px rgba(0,0,0,0.08);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.2rem;
`;

export const HeaderTitle = styled.h1`
  color: #23384a;
  font-size: 2rem;
  margin: 0;
`;

export const HeaderSub = styled.p`
  color: #6b7b86;
  margin: 0;
  font-size: 1rem;
`;

export const HeaderActions = styled.div`
  display: flex;
  gap: 0.8rem;
  flex-wrap: wrap;
`;

export const PrimaryBtn = styled.button`
  background: #e74c3c;
  color: #fff;
  border: none;
  padding: 0.75rem 1.2rem;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  &:hover { background: #d84332; }
`;

export const GhostBtn = styled.button`
  background: #7f9b9a;
  color: #fff;
  border: none;
  padding: 0.75rem 1.2rem;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  &:hover { filter: brightness(0.95); }
`;

export const DetailGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-top: 0.8rem;

  @media (min-width: 960px) {
    grid-template-columns: 1fr 1fr;
  }
`;

export const InfoCard = styled.div`
  background: #ffffff;
  border-radius: 14px;
  box-shadow: 0 6px 22px rgba(0,0,0,0.08);
  padding: 1.2rem 1.4rem;
`;

export const SectionTitle = styled.h3`
  color: #23384a;
  font-size: 1.2rem;
  margin: 0 0 0.8rem 0;
`;

export const KV = styled.div`
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.6rem;
  padding: 0.9rem 0;
  border-bottom: 1px solid #e8eef2;

  &:last-child { border-bottom: none; }
`;

export const Key = styled.span`
  color: #6b7b86;
`;

export const Value = styled.span`
  color: #23384a;
  font-weight: 600;
`;

export const ContactBox = styled.div`
  background: #f4f7f9;
  border: 1px solid #e1e8ee;
  border-radius: 10px;
  padding: 0.9rem 1rem;
  display: grid;
  gap: 0.6rem;
`;

export const ContactRow = styled.div`
  display: flex;
  align-items: center;
  gap: 0.6rem;
  color: #23384a;
  font-size: 0.95rem;
`;

export const AboutCard = styled(InfoCard)`
  grid-column: 1 / -1;
`;

export const Bullet = styled.li`
  margin: 0.25rem 0;
  color: #23384a;
`;

export const SuccessAlert = styled.div`
  background: #d4edda;
  border: 1px solid #c3e6cb;
  color: #155724;
  padding: 0.9rem 1rem;
  border-radius: 8px;
  margin-bottom: 0.8rem;
`;

export const FormField = styled.input`
  width: 100%;
  padding: 0.85rem;
  border-radius: 10px;
  border: 1px solid #ccd8e0;
  margin: 0.35rem 0 0.8rem;
  font-size: 0.95rem;
  &:focus { outline: none; border-color: #9fb6c4; }
`;

export const TextArea = styled.textarea`
  width: 100%;
  padding: 0.85rem;
  border-radius: 10px;
  border: 1px solid #ccd8e0;
  margin: 0.35rem 0 0.8rem;
  min-height: 110px;
  font-size: 0.95rem;
  resize: vertical;
  &:focus { outline: none; border-color: #9fb6c4; }
`;

export const SubmitBtn = styled.button`
  background: #e67e22;
  color: #fff;
  border: none;
  padding: 0.85rem 1.2rem;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  &:hover { background: #d06f17; }
`;

// ====================== PAGINATION ======================
export const PaginationWrapper = styled.div`
  margin-top: 35px;
  text-align: center;
  display: flex;
  justify-content: center;
  gap: 12px;
  align-items: center;
`;

export const PageButton = styled.button`
  background: ${(props) => (props.disabled ? "#dcdcdc" : "#3498db")};
  color: ${(props) => (props.disabled ? "#7f8c8d" : "#fff")};
  border: none;
  padding: 10px 18px;
  border-radius: 8px;
  font-size: 0.95rem;
  cursor: ${(props) => (props.disabled ? "not-allowed" : "pointer")};
  transition: 0.3s;

  &:hover {
    background: ${(props) => 
      props.disabled ? "#dcdcdc" : "#2980b9"};
  }
`;

export const PageInfo = styled.span`
  font-size: 1rem;
  font-weight: 600;
  color: #2c3e50;
`;
