import React, { useState, useEffect } from "react";
import styled from "styled-components";
import axios from "axios";
import { BaseUrl } from "../../BaseUrl"; // ✅ make sure file exists in src/BaseUrl.js

// ====== Styled Components ======
const AddSpotContainer = styled.div`
  background: #fff;
  padding: 2rem 2.5rem;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.05);
  width: 80%;
  max-width: 950px;
  margin: 1.5rem auto;
`;

const AddSpotHeader = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
`;

const AddSpotTitle = styled.h2`
  font-size: 1.25rem;
  color: #2c3e50;
  font-weight: 600;
  margin: 0;
`;

const BackButton = styled.button`
  background: #f0f2f5;
  color: #2c3e50;
  font-weight: 500;
  border: none;
  border-radius: 20px;
  padding: 0.4rem 1.2rem;
  cursor: pointer;
  font-size: 0.9rem;
  transition: all 0.2s ease;
  &:hover {
    background: #e0e3e8;
  }
`;

const AddSpotForm = styled.form`
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem 1.5rem;
  margin-top: 1rem;
`;

const FormGroup = styled.div`
  display: flex;
  flex-direction: column;
`;

const Label = styled.label`
  font-size: 0.9rem;
  color: #34495e;
  font-weight: 500;
  margin-bottom: 0.3rem;
  span {
    color: red;
  }
`;

const Input = styled.input`
  padding: 0.55rem 0.7rem;
  border: 1.5px solid #d0d7e2;
  border-radius: 6px;
  font-size: 0.9rem;
  background: #fafafa;
  transition: all 0.2s ease;
  &:focus {
    outline: none;
    border-color: #2980b9;
    background: white;
  }
`;

const Select = styled.select`
  padding: 0.55rem 0.7rem;
  border: 1.5px solid #d0d7e2;
  border-radius: 6px;
  font-size: 0.9rem;
  background: #fafafa;
  transition: all 0.2s ease;
  &:focus {
    outline: none;
    border-color: #2980b9;
    background: white;
  }
`;

const CoordinateGroup = styled.div`
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
`;

const TextArea = styled.textarea`
  grid-column: 1 / -1;
  padding: 0.6rem 0.8rem;
  border: 1.5px solid #d0d7e2;
  border-radius: 8px;
  font-size: 0.9rem;
  min-height: 90px;
  resize: none;
  background: #fafafa;
  &:focus {
    outline: none;
    border-color: #2980b9;
    background: white;
  }
`;

const FormButton = styled.button`
  grid-column: 0 / -1;
  margin-top: 0.8rem;
  background: #2ecc71;
  color: white;
  border: none;
  border-radius: 30px;
  padding: 0.8rem;
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  transition: all 0.3s ease;
  &:hover {
    background: #27ae60;
    transform: translateY(-1px);
  }
`;

const Divider = styled.hr`
  border: none;
  border-top: 1px solid #eaeaea;
  margin: 0.8rem 0 1.5rem;
`;



// ====== Component ======
const AddSpotPage = ({ setShowAddPage, fetchSpots, editData }) => {
  const pflegeUserId = localStorage.getItem("pflegeUserId");
  const token = localStorage.getItem("pflegeUserToken");
  const initialFormState = {
    name_of_the_place: "",
    room_type: "",
    care_level: "",
    availability: "",
    price_per_month: "",
    latitude: "",
    longitude: "",
    description: "",
    city: "",
    postal_code: "",
    user_id: pflegeUserId,
  };
  const [formData, setFormData] = useState(initialFormState);
  const [successMsg, setSuccessMsg] = useState("");

  useEffect(() => {
    if (editData) {
      // Populate fields with selected spot data
      setFormData({
        name_of_the_place: editData.name_of_the_place || "",
        room_type: editData.room_type || "",
        care_level: editData.care_level || "",
        availability: editData.availability || "",
        price_per_month: editData.price_per_month || "",
        latitude: editData.latitude || "",
        longitude: editData.longitude || "",
        postal_code: editData.postal_code || "",
        city: editData.city || "",
        description: editData.description || "",
        user_id: pflegeUserId,
      });
    } else {
      // Reset form when creating a new spot
      setFormData(initialFormState);
    }
  }, [editData]);


  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!token) {
      alert("Bitte zuerst einloggen!");
      return;
    }

    try {
      let response;

      if (editData) {
        // ✏️ Update existing spot
        response = await axios.put(`${BaseUrl}updatespot/${editData.id}`, formData, {
          headers: {
            Authorization: `Bearer ${token}`,
            Accept: 'application/json', // optional but recommended
          },
        });
      } else {
        // 🟢 Add new spot
        response = await axios.post(`${BaseUrl}addspot`, formData, {
          headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
        });
      }


      if (response.data) {
        // alert(editData ? "Spot erfolgreich aktualisiert!" : "Neuer Spot hinzugefügt!");?
        setSuccessMsg(editData ? "Spot erfolgreich aktualisiert!" : "Neuer Spot hinzugefügt!");
        await fetchSpots(); // ✅ Reload data from API
        // setShowAddPage(false);
      }
    } catch (error) {
      console.error("Error adding/updating spot:", error.response?.data || error.message);
      alert("Fehler beim Speichern des Spots!");
    }
  };

  return (
    <AddSpotContainer>
      <AddSpotHeader>
        <AddSpotTitle>
          {editData ? "Pflegeplatz bearbeiten" : "Neuen Pflegeplatz hinzufügen"}
        </AddSpotTitle>
        <BackButton onClick={() => setShowAddPage(false)}>← zurück</BackButton>
      </AddSpotHeader>

      <Divider />

      {successMsg && (
        <div style={{
          background: "#dfffe2",
          padding: "10px",
          marginBottom: "15px",
          borderRadius: "6px",
          color: "#2d7d3e",
          fontWeight: "600"
        }}>
          {successMsg}
        </div>
      )}
      <AddSpotForm onSubmit={handleSubmit}>

        <FormGroup>
          <Label>Spot Name <span>*</span></Label>
          <Input
            type="text"
            name="name_of_the_place"
            value={formData.name_of_the_place}
            onChange={handleInputChange}
            required
          />
        </FormGroup>

        <FormGroup>
          <Label>Zimmertyp <span>*</span></Label>
          <Select
            name="room_type"
            value={formData.room_type}
            onChange={handleInputChange}
            required
          >
            <option value="">Bitte auswählen</option>
            <option value="1">Einzelzimmer</option>
            <option value="2">Doppelzimmer</option>
          </Select>
        </FormGroup>

        <FormGroup>
          <Label>Pflegegrad <span>*</span></Label>
          <Select
            name="care_level"
            value={formData.care_level}
            onChange={handleInputChange}
            required
          >
            <option value="">Bitte auswählen</option>
            <option value="1">Stufe 1</option>
            <option value="2">Stufe 2</option>
            <option value="3">Stufe 3</option>
          </Select>
        </FormGroup>

        <FormGroup>
          <Label>Verfügbarkeit <span>*</span></Label>
          <Select
            name="availability"
            value={formData.availability}
            onChange={handleInputChange}
            required
          >
            <option value="">Bitte auswählen</option>
            <option value="1">Sofort</option>
            <option value="2">Kurzfristig</option>
            <option value="3">1–3 Monate</option>
          </Select>
        </FormGroup>

        <FormGroup>
          <Label>Preis pro Monat <span>*</span></Label>
          <Input
            type="text"
            name="price_per_month"
            value={formData.price_per_month}
            onChange={handleInputChange}
            required
          />
        </FormGroup>
         <FormGroup>
          <Label>Postleitzahl <span>*</span></Label>
          <Input
            type="text"
            name="postal_code"
            value={formData.postal_code}
            onChange={handleInputChange}
            required
          />
        </FormGroup>

         <FormGroup>
          <Label>Stadt<span>*</span></Label>
          <Input
            type="text"
            name="city"
            value={formData.city}
            onChange={handleInputChange}
            required
          />
        </FormGroup>


        <CoordinateGroup>
          <FormGroup>
            <Label>Breitengrad</Label>
            <Input
              type="text"
              name="latitude"
              value={formData.latitude}
              onChange={handleInputChange}
            />
          </FormGroup>

          <FormGroup>
            <Label>Längengrad</Label>
            <Input
              type="text"
              name="longitude"
              value={formData.longitude}
              onChange={handleInputChange}
            />
          </FormGroup>
        </CoordinateGroup>

        <FormGroup style={{ gridColumn: "1 / -1" }}>
          <Label>Beschreibung</Label>
          <TextArea
            name="description"
            value={formData.description}
            onChange={handleInputChange}
          />
        </FormGroup>

        <FormButton type="submit">
          {editData ? "Aktualisieren" : "Jetzt hinzufügen"}
        </FormButton>
      </AddSpotForm>
    </AddSpotContainer>
  );
};

export default AddSpotPage;
